+% ---------------------------------------------------------------
+\section{Surjective Pullback Firewall}
+% ---------------------------------------------------------------
+
+\begin{definition}[Adelic pullback form]\label{def:bwadel}
+For $F,G\in\mathcal{S}_{\mathrm{adel}}^{\mathrm{amp}}$ set
+\[
+  B_W^{\mathrm{adel}}(F,G)
+  := B_W(R_{\mathrm{PW}}F,R_{\mathrm{PW}}G).
+\]
+\end{definition}
+
+\begin{proposition}[Pullback firewall]\label{prop:pullback-firewall}
+The form $B_W^{\mathrm{adel}}$ is Hermitian sesquilinear and satisfies:
+\begin{enumerate}
+\item $\ker R_{\mathrm{PW}}\subset\operatorname{Rad}(B_W^{\mathrm{adel}})$;
+\item the induced map
+\[
+  \mathcal{S}_{\mathrm{adel}}^{\mathrm{amp}}/\ker R_{\mathrm{PW}}
+  \longrightarrow \mathcal{A}_{\mathrm{PW}}
+\]
+is a vector-space isomorphism;
+\item
+\[
+  B_W^{\mathrm{adel}}(F,F)\ge0\ \forall F
+  \quad\Longleftrightarrow\quad
+  B_W(a,a)\ge0\ \forall a\in\mathcal{A}_{\mathrm{PW}}.
+\]
+\end{enumerate}
+\begin{proof}
+Hermitian sesquilinearity is preserved by pullback. If
+$F\in\ker R_{\mathrm{PW}}$, then
+$B_W^{\mathrm{adel}}(F,G)=B_W(0,R_{\mathrm{PW}}G)=0$ for every $G$.
+Surjectivity of $R_{\mathrm{PW}}$ gives the quotient isomorphism.
+The forward implication in (3) follows by applying positivity to the explicit
+section $S_{\mathrm{PW}}a:=F_a$ from Proposition~\ref{prop:rpw-surjective};
+the reverse implication is immediate from the definition.
+\end{proof}
+\end{proposition}
+
+\begin{remark}[No new positivity from the port]
+Proposition~\ref{prop:pullback-firewall} is a structural limitation, not a
+negative statement about the usefulness of the adelic source. The port is a
+genuine RH-free construction, but it transports the complete Weil form without
+strengthening its sign. By the classical Weil criterion, global positivity of
+either $B_W$ or its adelic pullback is exactly the RH positivity problem.
+\end{remark}
